using System.Linq; using System.Web.Mvc; using MaSV_LTW_MyStore.Models; namespace MaSV_LTW_MyStore.Controllers { public class CategoriesController:Controller { private StoreContext db=new StoreContext(); public ActionResult Index(){return View(db.Categories.OrderBy(c=>c.CategoryName).ToList());} protected override void Dispose(bool disposing){if(disposing)db.Dispose();base.Dispose(disposing);} } }